import { test, expect } from '@playwright/test';

test.describe('Async Data Fetching', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000'); // Replace with your app's URL
  });

  test('should render the initial page without blocking', async ({ page }) => {
    const initialContent = await page.getByText('Initial Content'); // Replace with actual initial content
    await expect(initialContent).toBeVisible();
  });

  test('should fetch data asynchronously and display it', async ({ page }) => {
    await page.waitForTimeout(1000); // Wait for async data fetching to complete
    const asyncContent = await page.getByText('Async Fetched Content'); // Replace with actual async content
    await expect(asyncContent).toBeVisible();
  });
});
